// A0 fixtures and golden metrics (#56, docs/strategy/11 §4): the committed FICTIONAL fixtures
// (>= 12 per forum id) pass the golden harness, every anchor is verbatim in its page, and over
// documents generated by seed the full pipeline (skeleton + a recorded model with injected faults +
// validators) reaches row precision >= 98%, anchor validity 100% and zero hallucinated dates.
// Real district fixtures are validated later with #119 and are not needed here.
import { readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

import { datePresence } from '@causedeck/intelligence/extract';
import { describe, expect, it } from 'vitest';

import { layoutFromPdf } from '../../layout/pdf.ts';
import {
  FIXTURES_ROOT,
  FixtureManifestSchema,
  pageTexts,
  runGolden,
} from '../../testing/golden.ts';
import { LayoutDocumentSchema, ParsedCauseListSchema } from '../../types.ts';
import {
  createA0Adapter,
  parseListA0,
  parseOrderA0,
  buildCaseTypeLookup,
  A0_ADAPTER_IDS,
} from '../index.ts';
import {
  A0_SCENARIOS,
  A0_SYNTHETIC_FORUMS,
  generateA0Document,
  ocrSidecar,
  type GeneratedA0Document,
} from '../synthetic/generate.ts';

import {
  fakeGateway,
  must,
  pagesOf,
  recordedListModel,
  recordedOrderModel,
  scope,
} from './helpers.ts';

const THRESHOLDS = JSON.parse(
  readFileSync(path.resolve(import.meta.dirname, '../../../eval/a0/thresholds.json'), 'utf8'),
) as {
  minRowPrecision: number;
  anchorValidity: number;
  hallucinatedDates: number;
  minFixturesPerForum: number;
};
const lookup = buildCaseTypeLookup([]);
const SEEDS = [56, 5601, 5602];

describe('committed A0 fixtures', () => {
  it.each(A0_ADAPTER_IDS)(
    '%s: at least 12 synthetic FICTIONAL fixtures, each with an expected file',
    (id) => {
      const dir = path.join(FIXTURES_ROOT, id);
      const manifest = FixtureManifestSchema.parse(
        JSON.parse(readFileSync(path.join(dir, 'manifest.json'), 'utf8')),
      );
      expect(manifest.classification).toBe('FICTIONAL');
      expect(manifest.fixtures.length).toBeGreaterThanOrEqual(THRESHOLDS.minFixturesPerForum);
      const files = readdirSync(dir);
      for (const entry of manifest.fixtures) {
        expect(entry.origin).toBe('synthetic');
        expect(entry.classification).toBe('FICTIONAL');
        expect(files).toContain(entry.file.replace(/\.input\.[^.]+$/, '.expected.json'));
      }
      const kinds = new Set(manifest.fixtures.map((f) => f.kind));
      expect(kinds).toEqual(new Set(['cause_list', 'order']));
      // English, Tamil, Kannada and mixed orders, Com.O.S., CNR, image-only and malformed cases.
      for (const scenario of A0_SCENARIOS) {
        expect(
          manifest.fixtures.some((f) => f.file.startsWith(`${scenario}.input.`)),
          scenario,
        ).toBe(true);
      }
    },
  );

  it.each(A0_ADAPTER_IDS)(
    '%s: passes the golden harness with every anchor verbatim in its page',
    async (id) => {
      const report = await runGolden(id, {
        adapter: createA0Adapter({ id }),
        privateFixturesDir: null,
      });
      for (const c of report.public.cases)
        expect(c.diff.concat(c.anchorViolations), c.file).toEqual([]);
      expect(report.public.passed).toBe(true);
      expect(report.public.cases.length).toBeGreaterThanOrEqual(THRESHOLDS.minFixturesPerForum);
    },
  );

  it.each(A0_ADAPTER_IDS)(
    '%s: an image-only PDF needs OCR, and its OCR sidecar parses to the truth',
    async (id) => {
      const dir = path.join(FIXTURES_ROOT, id);
      const layout = await layoutFromPdf(
        new Uint8Array(readFileSync(path.join(dir, 'list-image-only.input.pdf'))),
      );
      const adapter = createA0Adapter({ id });
      const forum = must(A0_SYNTHETIC_FORUMS.find((f) => f.adapterId === id));
      const scanned = await adapter.parseCauseList({
        kind: 'layout',
        layout,
        meta: { receivedAt: '2026-10-21T04:00:00.000Z', forumCode: forum.forumCode },
      });
      expect(scanned.status).toBe('needs_ocr');
      expect(scanned.rows).toEqual([]);
      const sidecar = LayoutDocumentSchema.parse(
        JSON.parse(readFileSync(path.join(dir, 'list-image-only.ocr.json'), 'utf8')),
      );
      const ocr = await adapter.parseCauseList({
        kind: 'layout',
        layout: sidecar,
        meta: { receivedAt: '2026-10-21T04:00:00.000Z', forumCode: forum.forumCode },
      });
      const truth = generateA0Document(forum, 'list-image-only', 56).truth;
      expect(ocr.status).toBe('ok');
      expect(
        ocr.rows.map((r) => `${r.caseType ?? ''}/${r.caseNumber ?? ''}/${String(r.caseYear)}`),
      ).toEqual(truth.cases.map((c) => `${c.caseType}/${c.caseNumber}/${String(c.caseYear)}`));
      expect(ocrSidecar(generateA0Document(forum, 'list-image-only', 56))).toEqual(sidecar);
    },
  );

  it.each(A0_ADAPTER_IDS)(
    '%s: every expected cause-list parses with the framework schema',
    (id) => {
      const dir = path.join(FIXTURES_ROOT, id);
      for (const name of readdirSync(dir).filter((n) => /^list-.*\.expected\.json$/.test(n))) {
        const parsed = ParsedCauseListSchema.parse(
          JSON.parse(readFileSync(path.join(dir, name), 'utf8')),
        );
        expect(parsed.adapterId).toBe(id);
        for (const row of parsed.rows) expect(row.confidence).toBeLessThanOrEqual(0.6);
      }
    },
  );
});

interface Tally {
  rows: number;
  correct: number;
  anchors: number;
  validAnchors: number;
  dates: number;
  hallucinated: number;
  rejectedFaults: number;
  missed: number;
  truthRows: number;
}

function newTally(): Tally {
  return {
    rows: 0,
    correct: 0,
    anchors: 0,
    validAnchors: 0,
    dates: 0,
    hallucinated: 0,
    rejectedFaults: 0,
    missed: 0,
    truthRows: 0,
  };
}

async function scoreList(doc: GeneratedA0Document, tally: Tally): Promise<void> {
  const { gateway } = fakeGateway(() => recordedListModel(doc, { faults: true }));
  const r = await parseListA0({
    documentId: 'eval',
    forumCode: doc.forum.forumCode,
    pages: pagesOf(doc.pages),
    ...(doc.layout === undefined ? {} : { layout: doc.layout }),
    lookup,
    ai: { gateway, scope },
  });
  const truth = new Set(
    doc.truth.cases.map((c) => `${c.caseType}/${c.caseNumber}/${String(c.caseYear)}`),
  );
  const got = new Set<string>();
  for (const row of r.list.rows) {
    const ref = must(row.caseRef);
    const key = `${ref.caseType}/${ref.caseNumber}/${String(ref.caseYear)}`;
    got.add(key);
    tally.rows += 1;
    if (truth.has(key)) tally.correct += 1;
    tally.anchors += 1;
    const page = doc.pages[row.anchor.page - 1] ?? '';
    if (page.slice(row.anchor.charStart, row.anchor.charEnd) === row.anchor.quote)
      tally.validAnchors += 1;
    for (const date of row.dates ?? []) {
      tally.dates += 1;
      if (datePresence(date.iso, date.anchor.quote) === null) tally.hallucinated += 1;
    }
  }
  tally.truthRows += truth.size;
  for (const key of truth) if (!got.has(key)) tally.missed += 1;
  // The model's faults (an invented row, a wrong case number, an absent date) were all refused.
  tally.rejectedFaults += r.list.rejected.length;
}

async function scoreOrder(doc: GeneratedA0Document, tally: Tally): Promise<void> {
  const { gateway } = fakeGateway(() => recordedOrderModel(doc));
  const r = await parseOrderA0({
    documentId: '30000000-0000-4000-8000-000000000000',
    forumCode: doc.forum.forumCode,
    pages: pagesOf(doc.pages),
    lookup,
    ai: { gateway, scope },
  });
  const e = r.order.extraction;
  const text = doc.pages.join('\n');
  const dates = [
    e.orderDate?.date,
    e.nextDate?.derived === true ? undefined : e.nextDate?.date,
    ...e.candidates.map((c) => c.date),
  ];
  for (const date of dates) {
    if (date === undefined) continue;
    tally.dates += 1;
    if (datePresence(date, text) === null) tally.hallucinated += 1;
  }
  for (const anchor of [
    e.orderDate?.anchor,
    e.nextDate?.anchor,
    ...e.caseNumbers.map((c) => c.anchor),
  ]) {
    if (anchor === undefined) continue;
    tally.anchors += 1;
    const page = doc.pages[anchor.page - 1] ?? '';
    if (page.slice(anchor.charStart, anchor.charEnd) === anchor.quote) tally.validAnchors += 1;
  }
  // Truth: the order date and the next date (literal or derived by code) are found, and a decoy
  // date is never the next date.
  if (doc.truth.orderDate !== undefined) expect(e.orderDate?.date).toBe(doc.truth.orderDate);
  if (doc.truth.nextDate !== undefined) expect(e.nextDate?.date).toBe(doc.truth.nextDate);
  else expect(e.nextDate).toBeUndefined();
  for (const c of doc.truth.cases) {
    tally.truthRows += 1;
    const found = r.order.identities.some(
      (i) =>
        i.caseRef?.caseType === c.caseType &&
        i.caseRef.caseNumber === c.caseNumber &&
        i.caseRef.caseYear === c.caseYear,
    );
    if (!found) tally.missed += 1;
    if (c.cnr !== undefined) expect(r.order.cnrs.map((x) => x.value)).toContain(c.cnr);
  }
}

describe('A0 golden metrics on generated documents', () => {
  it('row precision >= 98%, anchor validity 100%, zero hallucinated dates, every model fault refused', async () => {
    const lists = newTally();
    const orders = newTally();
    for (const seed of SEEDS) {
      for (const forum of A0_SYNTHETIC_FORUMS) {
        for (const scenario of A0_SCENARIOS) {
          const doc = generateA0Document(forum, scenario, seed);
          if (doc.kind === 'cause_list') await scoreList(doc, lists);
          else await scoreOrder(doc, orders);
        }
      }
    }
    expect(lists.rows).toBeGreaterThan(0);
    expect(lists.correct / lists.rows).toBeGreaterThanOrEqual(THRESHOLDS.minRowPrecision);
    expect(lists.missed).toBe(0);
    expect(lists.validAnchors).toBe(lists.anchors);
    expect(orders.validAnchors).toBe(orders.anchors);
    expect(lists.hallucinated + orders.hallucinated).toBe(THRESHOLDS.hallucinatedDates);
    expect(orders.missed).toBe(0);
    expect(lists.rejectedFaults).toBeGreaterThan(0);
    expect(THRESHOLDS.anchorValidity).toBe(1);
  });

  it('is reproducible: the same seed gives the same documents', () => {
    const forum = must(A0_SYNTHETIC_FORUMS[0]);
    expect(generateA0Document(forum, 'list-mixed', 56)).toEqual(
      generateA0Document(forum, 'list-mixed', 56),
    );
    expect(generateA0Document(forum, 'list-mixed', 56).pages).not.toEqual(
      generateA0Document(forum, 'list-mixed', 57).pages,
    );
  });

  it('page texts of an input are the texts anchors quote (golden harness contract)', () => {
    const doc = generateA0Document(must(A0_SYNTHETIC_FORUMS[0]), 'list-english', 56);
    expect(
      pageTexts({
        kind: 'text',
        text: doc.pages.join('\f'),
        meta: { receivedAt: '2026-10-21T04:00:00.000Z', forumCode: 'generic.a0' },
      }),
    ).toEqual(doc.pages);
  });
});
